function cataloguePageWindow(page,pages){const count=Math.min(5,pages),start=Math.max(1,Math.min(page-2,pages-count+1));return Array.from({length:count},(_,i)=>start+i)}
// Catalogue state lives in the URL and memory; no buyer information is stored here.
let catalogueState={q:'',category:'',brands:[],facets:{},sort:'default',page:1};
let catalogueScroll=0,catalogueReturnFocus='',renderedRoute='',refreshCatalogue=null,catalogueHasPosition=false;
const copyFilterState=s=>({...s,brands:[...(s.brands||[])],facets:{...s.facets}});
const emptyFilters=(sort='default')=>({q:'',category:'',brands:[],facets:{},sort,page:1});
function facetValues(category,key){return [...new Set(products.filter(p=>p.category===category).map(p=>p.specs[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))}
function usefulFacetKeys(category){return (facetKeys[category]||[]).filter(k=>facetValues(category,k).length>1)}
function normalizeSearch(text){return String(text).normalize('NFKD').toLowerCase().replace(/(\d)\s*(gsm|mm|cm|ml)\b/g,'$1$2').replace(/[^a-z0-9]+/g,' ').trim()}
function queryTokens(query){let q=normalizeSearch(query);const aliases=[[/\b(?:printer|printing|photocopier|photocopy|copy) paper\b/g,'paper'],[/\b(?:ball pen|ball pens|ballpoint pen)\b/g,'ballpoint'],[/\b(?:colouring|coloring|color) pencils\b/g,'coloured pencils'],[/\bexercise books?\b/g,'exercise book']];for(const [pattern,to]of aliases)q=q.replace(pattern,to);return q.split(' ').filter(Boolean)}
function searchMatches(p,query){const words=normalizeSearch([p.name,p.summary,p.unit,p.brand,...(p.searchTerms||[]),...Object.values(p.specs)].join(' ')).split(' ');return queryTokens(query).every(token=>words.some(word=>{if(/\d/.test(token))return word===token;const stem=t=>t.length>3?t.replace(/s$/,''):t;return stem(word).startsWith(stem(token))}))}
function matchingProducts(s,ignoreFacet='',ignoreCategory=false,ignoreBrands=false){return products.filter(p=>searchMatches(p,s.q)&&(!s.category||ignoreCategory||p.category===s.category)&&(ignoreBrands||!(s.brands||[]).length||s.brands.includes(productBrand(p)))&&Object.entries(s.facets).every(([key,value])=>key===ignoreFacet||ignoreCategory||p.specs[key]===value))}
function cleanFilterState(s){const category=categories.some(c=>c[2]===s.category)?s.category:'';const keys=usefulFacetKeys(category);return {q:String(s.q||'').trim().slice(0,160),category,brands:[...new Set(s.brands||[])].filter(b=>brandValues(category).includes(b)).sort(),sort:s.sort==='name'?'name':'default',page:Math.max(1,Math.min(100000,Math.floor(Number(s.page)||1))),facets:Object.fromEntries(Object.entries(s.facets||{}).filter(([k,v])=>keys.includes(k)&&facetValues(category,k).includes(v)))}}
function readCatalogueState(){const raw=location.hash.split('?')[1];if(raw===undefined)return cleanFilterState(history.state?.lepetseFilters||catalogueState);const params=new URLSearchParams(raw);return cleanFilterState({q:params.get('q')||'',category:params.get('category')||'',brands:params.getAll('brand'),sort:params.get('sort')||'default',page:params.get('page')||1,facets:Object.fromEntries([...params].filter(([k])=>k.startsWith('f.')).map(([k,v])=>[k.slice(2),v]))})}
function catalogueHref(s=catalogueState){const p=new URLSearchParams(quotationMode()?quoteModeQuery():'');if(s.page>1)p.set('page',s.page);if(s.q)p.set('q',s.q);if(s.category)p.set('category',s.category);for(const b of s.brands||[])p.append('brand',b);if(s.sort!=='default')p.set('sort',s.sort);for(const [k,v]of Object.entries(s.facets).sort())p.set('f.'+k,v);return '#stationery'+(p.size?'?'+p.toString():'')}
function saveFilterUrl(){const hash=catalogueHref();if(location.hash!==hash)history.pushState({lepetseFilters:copyFilterState(catalogueState)},'',hash)}
function facetLabel(k){return {Weight:'Paper weight',Pages:'Page count'}[k]||k}
function facetMarkup(state,prefix){return usefulFacetKeys(state.category).map((key,i)=>{const options=facetValues(state.category,key).map(value=>{const count=matchingProducts({...state,facets:{...state.facets,[key]:value}},'').length;const selected=state.facets[key]===value;return `<option value="${esc(value)}" ${selected?'selected':''} ${count===0&&!selected?'disabled':''}>${esc(value)} (${count})</option>`}).join('');return `<div class="filter-field"><label for="${prefix}-facet-${i}">${facetLabel(key)}</label><select id="${prefix}-facet-${i}" data-spec-filter="${esc(key)}"><option value="">All</option>${options}</select></div>`}).join('')}
function categoryCount(state,category){return products.filter(p=>searchMatches(p,state.q)&&(!category||p.category===category)).length}
function brandValues(category){return [...new Set(products.filter(p=>!category||p.category===category).map(productBrand))].sort((a,b)=>a.localeCompare(b))}
function brandMarkup(state,prefix){const choices=brandValues(state.category).map((brand,i)=>{const count=matchingProducts(state,'',false,true).filter(p=>productBrand(p)===brand).length;const selected=(state.brands||[]).includes(brand);return `<label class="brand-choice" for="${prefix}-brand-${i}"><input id="${prefix}-brand-${i}" type="checkbox" value="${esc(brand)}" data-brand-choice ${selected?'checked':''} ${!count&&!selected?'disabled':''}><span>${esc(brand)}</span><small>${count}</small></label>`}).join('');return `<fieldset class="brand-choices"><legend>Brand</legend><div class="brand-options">${choices}</div></fieldset>`}
function toggleBrand(state,value,checked){const brands=new Set(state.brands||[]);if(checked)brands.add(value);else brands.delete(value);return {...state,brands:[...brands]}}
function desktopFilters(state){const all=categoryCount(state,'');return `<fieldset class="category-choices"><legend>Categories</legend>${[['','All products'],...categories.map(c=>[c[2],c[0]])].map(([id,label],i)=>{const count=categoryCount(state,id);return `<label for="category-${i}" class="category-choice ${state.category===id?'selected':''}"><input id="category-${i}" type="radio" name="category" value="${id}" data-category-choice ${state.category===id?'checked':''} ${!count&&state.category!==id?'disabled':''}><span>${label}</span><small>${count}</small></label>`}).join('')}</fieldset>${usefulFacetKeys(state.category).length?`<fieldset class="specification-choices"><legend>Specifications</legend>${facetMarkup(state,'desktop')}</fieldset>`:''}${brandMarkup(state,'desktop')}`}
function filterChips(state){const chips=[];if(state.q)chips.push(['q','Search: '+state.q]);if(state.category)chips.push(['category',categories.find(c=>c[2]===state.category)[0]]);for(const brand of state.brands||[])chips.push(['brand:'+brand,'Brand: '+brand]);for(const [k,v]of Object.entries(state.facets))chips.push(['facet:'+k,facetLabel(k)+': '+v]);return chips.map(([key,label])=>`<button class="filter-chip" data-remove-filter="${esc(key)}" aria-label="Remove ${esc(label)}">${esc(label)} <span aria-hidden="true">×</span></button>`).join('')}
function filterCount(s){return Number(!!s.category)+Object.keys(s.facets).length+(s.brands||[]).length}
const catalogueAdverts=[{id:'waltons-801215',title:'Mondi Rotatrim A4 paper',detail:'80 gsm · 500 sheets per ream',unit:'per ream',label:'Shop paper',category:'paper'},{id:'waltons-21924804',title:'Primeline blue ballpoint pen',detail:'1.0 mm · medium point',unit:'each',label:'Shop pens',category:'pens'},{id:'waltons-578138',title:'Croxley A4 lever arch file',detail:'70 mm spine · Rado locking',unit:'each',label:'Shop files',category:'files'},{id:'waltons-811436',title:'Croxley A4 examination pad',detail:'100 pages · feint and margin',unit:'each',label:'Shop notebooks',category:'books'},{id:'waltons-723117',title:'Stabilo Boss highlighters',detail:'Assorted colours · set of 4',unit:'per set of 4',label:'Shop highlighters',category:'pens'},{id:'waltons-302116',title:'Primeline colour pencils',detail:'12 colours · full set',unit:'per set of 12',label:'Shop art supplies',category:'art'}];
let catalogueAdvertIndex=0,advertTimer=null,advertPaused=false;
function catalogueAdvert(){const ad=catalogueAdverts[catalogueAdvertIndex],p=products.find(p=>p.id===ad.id),price=priceReferences[p.id];return `<div class="compact-advert-copy"><h1 id="catalogue-advert-title" tabindex="-1">Stationery catalogue</h1><div id="advert-content" aria-live="${advertPaused?'polite':'off'}" aria-atomic="true"><p><strong>${esc(ad.title)}</strong><br>${esc(ad.detail)}</p><div class="compact-advert-action">${quotationMode()?'':`<span class="compact-advert-price">${schoolMoney(price.amountMinor)} <small>${ad.unit}</small></span>`}<a class="btn dark" id="advert-shop" href="#stationery?category=${ad.category}${quotationMode()?'&mode=quote'+(rfqBuyer()?'&buyer='+rfqBuyer():''):''}">${ad.label}</a></div></div></div><div class="advert-image-area"><img class="compact-advert-product" src="${esc(p.image)}" alt="${esc(ad.title)}" fetchpriority="high"><div class="advert-controls" role="group" aria-label="Featured products">${catalogueAdverts.map((item,i)=>`<button type="button" class="advert-dot" data-advert-index="${i}" aria-label="Show ${item.title} advert" aria-pressed="${i===catalogueAdvertIndex}"><span aria-hidden="true"></span></button>`).join('')}</div></div>`}
function catalogue(){return `<section class="compact-product-advert" aria-labelledby="catalogue-advert-title"><div class="wrap compact-advert-layout" id="catalogue-advert">${catalogueAdvert()}</div></section><section class="catalogue-section"><div class="wrap catalogue-layout advanced-catalogue"><aside class="catalogue-filters advanced-filters" aria-label="Filter products" id="desktop-filters"></aside><div><div class="catalogue-tools catalogue-tools-compact"><span>${quotationMode()?(rfqBuyer()?'RFQ mode · pricing will be emailed after review.':'Quote mode · indicative prices.'):'Shopping preview · indicative prices, checkout payments unavailable.'}${quotationMode()?' <a href="#stationery">Switch to shopping</a>':''}</span><div><label for="catalogue-sort">Sort by</label><select id="catalogue-sort"><option value="default">Recommended</option><option value="name">Name A–Z</option></select></div></div><div class="mobile-filter-bar"><button class="btn outline" id="open-filters" aria-haspopup="dialog">Filters</button><span id="mobile-result-count"></span><a href="${quotationMode()?'#basket':'#cart'}">${quotationMode()?(rfqBuyer()?'RFQ basket':'Quote basket'):'Cart'} <span class="${quotationMode()?'basket-count':'cart-count'}"></span></a></div><div class="catalogue-results-line" id="catalogue-results-start"><span id="result-count" role="status" aria-live="polite" aria-atomic="true" tabindex="-1"></span><button class="clear-filters" id="reset-filters">Clear all</button></div><div id="active-filters" class="active-filters" aria-label="Active filters"></div><div class="product-grid" id="product-results"></div><nav class="catalogue-pagination" id="catalogue-pagination" aria-label="Product pages"></nav></div></div></section>`}
function bindCatalogue(){initCatalogueScroll();catalogueState=readCatalogueState();history.replaceState({lepetseFilters:copyFilterState(catalogueState)},'',location.href);$('#global-search').value=catalogueState.q;$('#catalogue-sort').value=catalogueState.sort;
function update(next,{focusId='',chipFocus=false,keepPage=false}={}){catalogueState=cleanFilterState({...next,page:keepPage?next.page:1});saveFilterUrl();draw();scrollCatalogueResults();if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});if(chipFocus)($('#active-filters button')||$('#result-count')).focus()}
const advertRoot=$('#catalogue-advert');let advertHovered=false;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');if(reducedMotion.matches)advertPaused=true;
function scheduleAdvert(){clearTimeout(advertTimer);advertTimer=null;if(advertPaused||advertHovered||document.hidden||advertRoot.contains(document.activeElement)||!advertRoot.isConnected)return;advertTimer=setTimeout(()=>{if(!advertRoot.isConnected)return;catalogueAdvertIndex=(catalogueAdvertIndex+1)%catalogueAdverts.length;advertRoot.innerHTML=catalogueAdvert();bindAdvert();scheduleAdvert()},5000)}
function bindAdvert(){const ad=catalogueAdverts[catalogueAdvertIndex];$('#advert-shop').onclick=e=>{e.preventDefault();update({...emptyFilters(),category:ad.category});$('#result-count').focus({preventScroll:true})};main.querySelectorAll('[data-advert-index]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.advertIndex);catalogueAdvertIndex=index;advertRoot.innerHTML=catalogueAdvert();bindAdvert();main.querySelector(`[data-advert-index="${index}"]`).focus({preventScroll:true});scheduleAdvert()})}
advertRoot.onmouseenter=()=>{advertHovered=true;scheduleAdvert()};advertRoot.onmouseleave=()=>{advertHovered=false;scheduleAdvert()};advertRoot.onfocusin=scheduleAdvert;advertRoot.onfocusout=()=>queueMicrotask(scheduleAdvert);const advertVisibility=()=>{if(!advertRoot.isConnected){clearTimeout(advertTimer);document.removeEventListener('visibilitychange',advertVisibility);return}scheduleAdvert()};document.addEventListener('visibilitychange',advertVisibility);bindAdvert();scheduleAdvert();

function draw(){let shown=matchingProducts(catalogueState);if(catalogueState.sort==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(shown.length/10));catalogueState.page=Math.min(catalogueState.page||1,pages);const start=(catalogueState.page-1)*10;history.replaceState({lepetseFilters:copyFilterState(catalogueState)},'',catalogueHref());$('#desktop-filters').innerHTML=desktopFilters(catalogueState);$('#active-filters').innerHTML=filterChips(catalogueState);$('#reset-filters').hidden=!catalogueState.q&&!catalogueState.category&&!Object.keys(catalogueState.facets).length&&!catalogueState.brands.length;$('#result-count').textContent=`${shown.length?`${start+1}–${Math.min(start+10,shown.length)} of `:''}${shown.length} product${shown.length===1?'':'s'}${catalogueState.q?' matching “'+catalogueState.q+'”':''}`;$('#mobile-result-count').textContent=`${shown.length} products`;$('#open-filters').textContent=`Filters${filterCount(catalogueState)?' ('+filterCount(catalogueState)+')':''}`;$('#product-results').innerHTML=shown.slice(start,start+10).map(productCard).join('')||`<div class="empty"><h2>No matching products</h2><p>Remove a filter above, clear all selections, or upload your list.</p><button class="btn outline" id="empty-reset">Clear all</button></div>`;$('#global-search').value=catalogueState.q;$('#catalogue-sort').value=catalogueState.sort;$('#catalogue-pagination').innerHTML=pages>1?`<button data-page="${catalogueState.page-1}" aria-label="Previous page" ${catalogueState.page===1?'disabled':''}>Prev</button>${cataloguePageWindow(catalogueState.page,pages).map(page=>`<button class="pagination-number" data-page="${page}" aria-label="Page ${page}" ${catalogueState.page===page?'aria-current="page"':''}>${page}</button>`).join('')}<button data-page="${catalogueState.page+1}" aria-label="Next page" ${catalogueState.page===pages?'disabled':''}>Next</button>`:'';main.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{update({...catalogueState,page:Number(e.dataset.page)},{keepPage:true});$('#result-count').focus({preventScroll:true})});
$('#catalogue-page-select')?.addEventListener('change',e=>{update({...catalogueState,page:Number(e.target.value)},{keepPage:true});$('#result-count').focus({preventScroll:true})});
main.querySelectorAll('[data-category-choice]').forEach(e=>e.onchange=()=>update({...catalogueState,category:e.value,facets:{}},{focusId:e.id}));main.querySelectorAll('[data-brand-choice]').forEach(e=>e.onchange=()=>update(toggleBrand(catalogueState,e.value,e.checked),{focusId:e.id}));main.querySelectorAll('[data-spec-filter]').forEach(e=>e.onchange=()=>{const next=copyFilterState(catalogueState);if(e.value)next.facets[e.dataset.specFilter]=e.value;else delete next.facets[e.dataset.specFilter];update(next,{focusId:e.id})});main.querySelectorAll('[data-remove-filter]').forEach(e=>e.onclick=()=>{const next=copyFilterState(catalogueState);const key=e.dataset.removeFilter;if(key==='q')next.q='';else if(key==='category'){next.category='';next.facets={}}else if(key.startsWith('brand:'))next.brands=next.brands.filter(b=>b!==key.slice(6));else delete next.facets[key.slice(6)];update(next,{chipFocus:true})});$('#empty-reset')?.addEventListener('click',()=>update(emptyFilters(catalogueState.sort),{chipFocus:true}));bindProducts();updateCount()}
$('#reset-filters').onclick=()=>update(emptyFilters(catalogueState.sort),{chipFocus:true});$('#catalogue-sort').onchange=e=>update({...catalogueState,sort:e.target.value},{focusId:'catalogue-sort'});$('#open-filters').onclick=()=>openMobileFilters(update);refreshCatalogue=q=>update({...catalogueState,q});draw()}
function openMobileFilters(onApply){const dialog=$('#filter-dialog');let draft=copyFilterState(catalogueState);function draw(focusId=''){dialog.innerHTML=`<div class="filter-dialog-header"><h2 id="filter-dialog-title">Filter products</h2><button type="button" id="close-filters" aria-label="Close filters">×</button></div><div class="filter-dialog-body">${draft.q?`<p class="help">Search: ${esc(draft.q)}</p>`:''}<div class="filter-field"><label for="mobile-category">Category</label><select id="mobile-category">${[['','All products'],...categories.map(c=>[c[2],c[0]])].map(([id,label])=>{const count=categoryCount(draft,id);return `<option value="${id}" ${draft.category===id?'selected':''} ${count===0&&draft.category!==id?'disabled':''}>${label} (${count})</option>`}).join('')}</select></div>${facetMarkup(draft,'mobile')}${brandMarkup(draft,'mobile')}</div><div class="filter-dialog-footer"><button class="clear-filters" id="clear-draft">Clear all</button><button class="btn dark" id="apply-filters">Show ${matchingProducts(draft).length} product${matchingProducts(draft).length===1?'':'s'}</button></div>`;$('#close-filters').onclick=()=>dialog.close();$('#mobile-category').onchange=e=>{draft.category=e.target.value;draft.facets={};draft=cleanFilterState(draft);draw('mobile-category')};dialog.querySelectorAll('[data-brand-choice]').forEach(e=>e.onchange=()=>{draft=toggleBrand(draft,e.value,e.checked);draw(e.id)});dialog.querySelectorAll('[data-spec-filter]').forEach(e=>e.onchange=()=>{if(e.value)draft.facets[e.dataset.specFilter]=e.value;else delete draft.facets[e.dataset.specFilter];draw(e.id)});$('#clear-draft').onclick=()=>{draft=emptyFilters(draft.sort);draw('mobile-category')};$('#apply-filters').onclick=()=>{dialog.close();onApply(draft);$('#open-filters').focus({preventScroll:true})};if(focusId)document.getElementById(focusId)?.focus()};draw();dialog.showModal();$('#mobile-category').focus()}
function navigateCatalogueSearch(q){if(renderedRoute==='stationery'&&refreshCatalogue){refreshCatalogue(q);return}catalogueState=cleanFilterState({...emptyFilters(),q});location.hash=catalogueHref(catalogueState)}
function beforeCatalogueNavigation(){const next=(location.hash.slice(1)||'stationery').split('?')[0];if(renderedRoute==='stationery'&&next!=='stationery'){catalogueHasPosition=true;catalogueScroll=window.scrollY;catalogueReturnFocus=document.activeElement?.getAttribute('href')||''}}
function finishCatalogueNavigation(route){const returning=route==='stationery'&&renderedRoute!=='stationery'&&catalogueHasPosition;renderedRoute=route;document.body.classList.toggle('catalogue-active',route==='stationery');if(returning){requestAnimationFrame(()=>{const link=[...main.querySelectorAll('a')].find(a=>a.getAttribute('href')===catalogueReturnFocus);link?.focus({preventScroll:true});window.scrollTo(0,catalogueScroll)})}else if(route!=='stationery')window.scrollTo(0,0)}

function scrollCatalogueResults(){const anchor=document.getElementById('catalogue-results-start');if(!anchor)return;const bar=document.querySelector('.mobile-filter-bar');const headerHeight=document.querySelector('header')?.offsetHeight||0;const offset=headerHeight+(matchMedia('(max-width:800px)').matches?(bar?.offsetHeight||0)+12:20);const top=anchor.getBoundingClientRect().top;if(top<offset)window.scrollTo({top:Math.max(0,window.scrollY+top-offset),behavior:'instant'})}
let catalogueTopButton;function initCatalogueScroll(){if(catalogueTopButton)return;catalogueTopButton=document.createElement('button');catalogueTopButton.className='catalogue-back-top';catalogueTopButton.textContent='↑ Back to top';catalogueTopButton.hidden=true;catalogueTopButton.onclick=()=>{window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('.catalogue-heading h1')?.focus({preventScroll:true})};document.body.append(catalogueTopButton);function updateCatalogueTop(){if(!catalogueTopButton)return;catalogueTopButton.hidden=renderedRoute!=='stationery'||window.scrollY<700}window.addEventListener('scroll',updateCatalogueTop,{passive:true});window.addEventListener('hashchange',updateCatalogueTop);}
